import{_ as r,l as h,o as e,c as s,v as t,p as o,x as i,d as n,i as p,S as u}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"Hull-White","description":"","frontmatter":{"title":"Hull-White","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/hull-white.md","filePath":"quant/hull-white.md","lastUpdated":1789023840000}'),d={name:"quant/hull-white.md"};function c(E,a,m,B,A,H){const l=h("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="hull-white" tabindex="-1">Hull-White <a class="header-anchor" href="#hull-white" aria-label="Permalink to &quot;Hull-White&quot;">​</a></h1><div class="epigraph"><p>给 Vasicek 的漂移加上时间函数，使之精确重现今日的整条期限结构，同时保留均值回复与高斯短端，以便用树为路径依赖产品定价。</p><footer>—— Hull &amp; White, Pricing Interest-Rate Derivative Securities, Review of Financial Studies, 1990</footer></div><p><a href="/quant/vasicek-cir">Vasicek / CIR</a> 能写出封闭的零息债，却不能保证模型曲线等于今天的市场曲线。Hull 与 White（1990）把 Vasicek 的常数长期均值换成 \\(\\theta(t)\\)，让瞬时远期的初值条件被精确满足，于是香草工具的贴现与市场一致，剩余参数 \\(a,\\sigma\\) 用来对准期权。它是无套利短端模型，不是新的均衡。随后的三叉树（Hull–White, 1994）把同一动态变成可处理美式、障碍与结构化票据的格子。Ho–Lee 是 \\(a=0\\) 的特例；扩展 CIR 是把同样的时变漂移接到平方根扩散上。本篇写一因子 Hull–White：如何由市场曲线解出 \\(\\theta(t)\\)、树怎么保持均值回复、以及它相对 <a href="/quant/hjm">HJM</a> 仍是短端马尔可夫的代价。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>交易台的约束是：今天所有流动性好的互换与期货必须被模型重新定价到市场，误差只能留在期权。均衡模型做不到这一点，除非参数个数多到过拟合。无套利路线要求：取今日折现 \\(P(0,T)\\) 为初值，让短端的漂移成为 \\(T\\) 的确定性函数，把曲线锁住。同时仍希望状态是一维马尔可夫的，否则美式行权要在无穷维曲线上做动态规划。</p><p>Hull–White 的折中是：波动与回复速度保持常数（或最多分段常数），只让漂移吸收曲线。这样 \\(r_t\\) 仍是高斯马尔可夫，债券价格仍仿射，欧式期权仍有封闭或准封闭公式，美式用树。问题变成：\\(\\theta(t)\\) 是否由 \\(P(0,T)\\) 唯一确定、确定之后短端波动是否还够用来校准 cap / swaption，以及一因子是否会把斜率风险错算成平行风险。</p><h3 id="与-ho–lee、cir-的分工" tabindex="-1">与 Ho–Lee、CIR++ 的分工 <a class="header-anchor" href="#与-ho–lee、cir-的分工" aria-label="Permalink to &quot;与 Ho–Lee、CIR++ 的分工&quot;">​</a></h3><p>Ho 与 Lee（1986）的二项经济在连续极限里是无均值回复的高斯短端，曲线可拟合，但长端方差随 \\(T\\) 线性涨，远期会散开。Hull–White 把 Vasicek 的 \\(a\\) 留下，长端被压住。CIR++（Brigo–Mercurio）给 CIR 加确定性平移 \\(x_t+\\varphi(t)\\)，既贴曲线又保持正利率（在平移不太负时）。选 Hull–White 通常是因为高斯加三叉树在工程上最省：负利率可接受或可用位移对数正态另处理，计算稳定。选 CIR++ 是因为合同禁止负利率且你愿意放弃高斯期权公式。不要把「Hull–White」当成所有可拟合短端模型的别名。</p><p><span class="marginnote">\\(\\theta(t)\\) 不是货币政策路径。它是让模型远期等于市场远期所要求的漂移补丁，里面已经含了凸性。把它画成「隐含短端预期」再讲宏观故事，会把 Jensen 项讲成央行意图。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>一因子 Hull–White 的风险中性动态为</p> \\[dr_t = \\big(\\theta(t)-a r_t\\big)\\,dt + \\sigma\\,dW_t. \\]<p>令 \\(f(0,T)=-\\partial_T\\log P(0,T)\\) 为市场瞬时远期。匹配 \\(P(0,T)\\) 给出</p> \\[\\theta(t)=\\frac{\\partial f(0,t)}{\\partial t}+a f(0,t)+\\frac{\\sigma^2}{2a}(1-e^{-2at}), \\]<p>最后一项是凸性。零息债对 \\(r_t\\) 仍仿射，\\(B(t,T)=(1-e^{-a(T-t)})/a\\)，而 \\(A(t,T)\\) 现在显式依赖今日曲线，不再是常数 \\(b\\) 的函数。欧式债券期权与 Jamshidian 分解下的欧式 swaption 可解析或半解析。</p><p>三叉树：在 \\(r\\) 方向用均值回复把分叉概率调离对称，节点重组，保证再结合；\\(\\theta(t)\\) 在每个时间层用一颗零息债或折现因子反解，使树对市场曲线无套利。\\(\\sigma\\) 与 \\(a\\) 用 caplet 或欧式 swaption 校准，常取分段常数 \\(\\sigma(t)\\) 变成「广义 Hull–White」，马尔可夫性仍在，但校准自由度上升。</p><h3 id="从短端到可观测的关键利率" tabindex="-1">从短端到可观测的关键利率 <a class="header-anchor" href="#从短端到可观测的关键利率" aria-label="Permalink to &quot;从短端到可观测的关键利率&quot;">​</a></h3><p>树或封闭公式给出的是对 \\(r\\) 的希腊值。风险报告需要的是对市场曲线关键点的偏导。标准做法是把 \\(P(0,T)\\) 的输入扰动一个基点，重算 \\(\\theta(t)\\) 再重定价，得到关键利率久期。一因子模型里这些久期几乎共线：你不能指望 Hull–White 同时给出可信的 2s10s 斜率对冲比。斜率对冲要用两因子 Hull–White（短端加随机长期均值）或直接用 HJM / <a href="/quant/lmm">LMM</a> 的到期结构波动。一因子的正当用途是：曲线已经用外部模型对冲，剩下的凸性、美式与路径依赖用一棵树来定价。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>无套利的机制是：今日曲线被 \\(\\theta(t)\\) 锁死之后，未来曲线的形状仍只能沿 Vasicek 的 \\(B(\\tau)\\) 族变形。均值回复 \\(a\\) 决定冲击在到期轴上的衰减：\\(\\sigma\\) 是短端即时波动，\\(a\\) 大则长端几乎不动。这与主成分里「平行为主、长端略钝」的第一模式相近，所以一因子 Hull–White 对贴现类产品往往够用，对曲线期权（CMS、斜率香草）不够用。</p><p>高斯使折现因子的积分仍高斯，欧式期望能写成正态 CDF。这也是负利率的来源：树的下枝可以到负值，折现可以大于 1。位移或地板可以事后补，但那已改变扩散，不再是原文的 Hull–White。对冲上，因为状态一维，delta 对冲短端期货或一个互换就能对冲模型内全部曲线风险——这在模型内正确，在真实市场上错误，真实市场还有独立的斜率。工程上必须在模型外再套一层关键利率限制，承认模型对冲不足。</p><p><span class="marginnote">校准 cap 再去给 swaption 定价，是一因子模型的经典失败：两者对曲线模态的暴露不同。看到「Hull–White 校准了但 Bermudan 卖不出市场」，先问校准仪器是 cap 还是共终端 swaption，而不是先加节点。</span></p><h3 id="树的稳定性与均值回复" tabindex="-1">树的稳定性与均值回复 <a class="header-anchor" href="#树的稳定性与均值回复" aria-label="Permalink to &quot;树的稳定性与均值回复&quot;">​</a></h3><p>若 \\(a\\) 很大或时间步很长，对称三叉的概率会掉出 \\([0,1]\\)。Hull–White 用改变中心节点（或调整概率）保持回复，这是树能覆盖 Vasicek 过程的原因。步长与 \\(a,\\sigma\\) 不匹配时会出现负概率或振荡的 \\(\\theta(t)\\)，后者常常来自输入曲线未平滑：\\(\\theta(t)\\) 含 \\(f\\) 的导数，折线远期会让漂移尖刺，再传到美式价格。先把曲线修成光滑远期，再校准树，是数值问题不是模型问题。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>Hull–White 不解释曲线为什么是今天这个形状，只保证从今天出发无套利。它不能独立产生丰富的波动率曲面倾斜：\\(\\sigma\\) 常数时 caplet 波动随到期的形状主要由 \\(a\\) 决定，smile 没有。要 smile 需局部波动、随机波动或 <a href="/quant/lmm">LMM</a> 的位移 / SABR 混合。多曲线时代贴现用 OIS、预测用 LIBOR 或 SOFR 期限利率，一因子 \\(r\\) 不能一身二任；实务是 OIS 上建一个 Hull–White 做贴现，预测曲线另建或做基差扩散。</p><p>不要把逐日重校准的 \\(a,\\sigma\\) 当成稳定的风险因子：它们吸收了模型没写的斜率与微笑。不要用一因子树给 CMS 斜率产品标价还报告「已对冲」。不要在 Monte Carlo 里用欧拉却在树上用精确 \\(\\theta(t)\\) 而不对离散误差做同一套检查。扩展到两因子（G2++）能改善斜率，但仍是高斯短端，极端路径的负利率与相关性结构仍是模型风险。</p><p><span class="marginnote">Hull–White 与 HJM 高斯一因子在数学上往往等价：短端马尔可夫是 HJM 波动取指数衰减时的特例。写报告时应说清：你用的是短端状态的树，还是远期曲线的高维模拟。等价只在连续、同一波动结构下成立，离散实现并不自动等价。</span></p>',28)),(e(),o(u,null,{default:i(()=>[p(l,{id:"mermaid-78",class:"mermaid",graph:"flowchart%20TD%0A%20%20MKT%5B%22%E4%BB%8A%E6%97%A5%E6%9B%B2%E7%BA%BF%20P(0%2CT)%22%5D%20--%3E%20TH%5B%22%E8%A7%A3%E5%87%BA%20%CE%B8(t)%22%5D%0A%20%20VAS%5B%22Vasicek%3A%20a%2C%20%CF%83%22%5D%20--%3E%20HW%5B%22dr%20%3D%20(%CE%B8(t)-a%20r)%20dt%20%2B%20%CF%83%20dW%22%5D%0A%20%20TH%20--%3E%20HW%0A%20%20HW%20--%3E%20EU%5B%22%E6%AC%A7%E5%BC%8F%3A%20%E4%BB%BF%E5%B0%84%E5%80%BA%E5%88%B8%20%2F%20Jamshidian%22%5D%0A%20%20HW%20--%3E%20TR%5B%22%E4%B8%89%E5%8F%89%E6%A0%91%3A%20%E7%BE%8E%E5%BC%8F%E4%B8%8E%E8%B7%AF%E5%BE%84%E4%BE%9D%E8%B5%96%22%5D%0A%20%20HW%20--%3E%20LIM%5B%22%E6%9B%B2%E7%BA%BF%E5%8F%98%E5%8A%A8%E4%BB%8D%E6%98%AF%E4%B8%80%E7%BB%B4%22%5D%0A%20%20LIM%20--%3E%20CAL%5B%22%E7%94%A8%20cap%20%E6%88%96%20swaption%20%E6%A0%A1%E5%87%86%20a%2C%20%CF%83%22%5D%0A%20%20CAL%20--%3E%20MIS%5B%22%E6%96%9C%E7%8E%87%20%2F%20smile%20%E4%BB%8D%E9%9C%80%E6%A8%A1%E5%9E%8B%E5%A4%96%E5%A4%84%E7%90%86%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Hull–White（1990）给 Vasicek 加上时变漂移 \\(\\theta(t)\\)，精确拟合今日期限结构，短端仍是高斯均值回复。</li><li>\\(\\theta(t)\\) 由市场瞬时远期及其导数加上凸性项唯一确定；它不是宏观预期路径。</li><li>欧式可用仿射债券公式，美式与结构化产品用三叉树；Ho–Lee 是无回复特例。</li><li>一因子只能描述一种曲线模态，cap 与 swaption 不能指望同一套 \\(a,\\sigma\\) 同时校准。</li><li>多曲线、负利率政策与微笑，都要求在 Hull–White 之外加结构，而不是把 \\(\\sigma\\) 变成每日自由参数来假装解决。</li><li>出处：Hull &amp; White, <em>Review of Financial Studies</em>, 1990；实现见 Hull &amp; White, <em>Journal of Derivatives</em>, 1994；Ho &amp; Lee, <em>Journal of Finance</em>, 1986。</li></ul>',2))])}const W=r(d,[["render",c]]);export{f as __pageData,W as default};
